<?php defined('ABSPATH')||exit; function bluprint_blog_defaults(){ return [ 'enabled'=>1, 'title'=>'آخرین نوشته‌ها', 'mode'=>'latest', 'featured_order'=>[], 'manual_ids'=>[] ]; } function bluprint_blog_ids($ids){ if(!is_array($ids))$ids=preg_split('/[\s,]+/',(string)$ids,-1,PREG_SPLIT_NO_EMPTY); $ids=array_map('absint',$ids); $ids=array_filter($ids,fn($id)=>$id>0); return array_values(array_unique($ids)); } function bluprint_blog_sanitize($input){ $input=is_array($input)?$input:[]; $defaults=bluprint_blog_defaults(); $mode=$input['mode']??'latest'; return [ 'enabled'=>empty($input['enabled'])?0:1, 'title'=>sanitize_text_field($input['title']??$defaults['title']), 'mode'=>in_array($mode,['latest','featured','manual'],true)?$mode:'latest', 'featured_order'=>bluprint_blog_ids($input['featured_order']??[]), 'manual_ids'=>bluprint_blog_ids($input['manual_ids']??[]) ]; } function bluprint_blog_register_settings(){ register_setting('bluprint_blog_group','bluprint_blog_section',[ 'type'=>'array', 'sanitize_callback'=>'bluprint_blog_sanitize', 'default'=>bluprint_blog_defaults() ]); } add_action('admin_init','bluprint_blog_register_settings'); function bluprint_blog_add_menu(){ add_submenu_page('bluprint-settings','سکشن بلاگ','سکشن بلاگ','edit_theme_options','bluprint-blog','bluprint_blog_admin'); } add_action('admin_menu','bluprint_blog_add_menu'); function bluprint_blog_admin(){ if(!current_user_can('edit_theme_options'))return; $data=wp_parse_args(get_option('bluprint_blog_section',[]),bluprint_blog_defaults()); $posts=get_posts([ 'post_type'=>'post', 'post_status'=>'publish', 'posts_per_page'=>-1, 'orderby'=>'date', 'order'=>'DESC', 'fields'=>'ids' ]); $featured=get_posts([ 'post_type'=>'post', 'post_status'=>'publish', 'posts_per_page'=>-1, 'meta_key'=>'_bluprint_featured', 'meta_value'=>'1', 'fields'=>'ids' ]); $name='bluprint_blog_section'; ?> <div class="wrap"> <h1>تنظیمات سکشن بلاگ</h1> <form method="post" action="options.php"> <?php settings_fields('bluprint_blog_group'); ?> <table class="form-table" role="presentation"> <tr> <th scope="row">وضعیت سکشن</th> <td> <label> <input type="checkbox" name="<?php echo esc_attr($name); ?>[enabled]" value="1" <?php checked($data['enabled'],1); ?>> نمایش سکشن بلاگ در صفحه اصلی </label> </td> </tr> <tr> <th scope="row"> <label for="bp-blog-title">عنوان سکشن</label> </th> <td> <input id="bp-blog-title" class="regular-text" type="text" name="<?php echo esc_attr($name); ?>[title]" value="<?php echo esc_attr($data['title']); ?>"> </td> </tr> <tr> <th scope="row"> <label for="bp-blog-mode">منبع مقالات</label> </th> <td> <select id="bp-blog-mode" name="<?php echo esc_attr($name); ?>[mode]"> <option value="latest" <?php selected($data['mode'],'latest'); ?>>آخرین نوشته‌ها</option> <option value="featured" <?php selected($data['mode'],'featured'); ?>>نوشته‌های منتخب</option> <option value="manual" <?php selected($data['mode'],'manual'); ?>>انتخاب دستی</option> </select> </td> </tr> <tr> <th scope="row">ترتیب نوشته‌های منتخب</th> <td> <p class="description">شناسه نوشته‌ها را با کاما وارد کن. ترتیب نمایش از چپ به راست است. فقط نوشته‌های علامت‌گذاری‌شده به‌عنوان منتخب نمایش داده می‌شوند.</p> <input class="large-text" type="text" dir="ltr" name="<?php echo esc_attr($name); ?>[featured_order]" value="<?php echo esc_attr(implode(',',$data['featured_order'])); ?>"> <p class="description">شناسه نوشته‌های منتخب: <?php echo esc_html(implode(', ',$featured)); ?></p> </td> </tr> <tr> <th scope="row">انتخاب دستی مقالات</th> <td> <p class="description">شناسه حداکثر سه نوشته را با کاما وارد کن. ترتیب شناسه‌ها، ترتیب نمایش کارت‌ها را مشخص می‌کند.</p> <input class="large-text" type="text" dir="ltr" name="<?php echo esc_attr($name); ?>[manual_ids]" value="<?php echo esc_attr(implode(',',$data['manual_ids'])); ?>"> <p class="description">شناسه نوشته‌های منتشرشده:</p> <div style="max-height:220px;overflow:auto;background:#fff;border:1px solid #ddd;padding:12px;max-width:600px"> <?php foreach($posts as $post_id): ?> <div style="display:flex;gap:10px;padding:4px 0"> <code><?php echo esc_html($post_id); ?></code> <span><?php echo esc_html(get_the_title($post_id)); ?></span> </div> <?php endforeach; ?> </div> </td> </tr> </table> <?php submit_button('ذخیره تنظیمات'); ?> </form> </div> <?php } function bluprint_blog_featured_metabox(){ add_meta_box( 'bluprint-blog-featured', 'وضعیت مقاله', 'bluprint_blog_featured_metabox_html', 'post', 'side', 'default' ); } add_action('add_meta_boxes','bluprint_blog_featured_metabox'); function bluprint_blog_featured_metabox_html($post){ wp_nonce_field('bluprint_blog_featured_save','bluprint_blog_featured_nonce'); $featured=get_post_meta($post->ID,'_bluprint_featured',true); ?> <label> <input type="checkbox" name="bluprint_blog_featured" value="1" <?php checked($featured,'1'); ?>> نمایش به‌عنوان نوشته منتخب </label> <?php } function bluprint_blog_featured_save($post_id){ if(!isset($_POST['bluprint_blog_featured_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bluprint_blog_featured_nonce'])),'bluprint_blog_featured_save'))return; if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return; if(!current_user_can('edit_post',$post_id))return; if(isset($_POST['bluprint_blog_featured'])){ update_post_meta($post_id,'_bluprint_featured','1'); }else{ delete_post_meta($post_id,'_bluprint_featured'); } } add_action('save_post_post','bluprint_blog_featured_save'); function bluprint_get_blog_data(){ return wp_parse_args(get_option('bluprint_blog_section',[]),bluprint_blog_defaults()); } function bluprint_get_blog_posts($limit=3){ $data=bluprint_get_blog_data(); $limit=max(1,min(3,absint($limit))); $args=[ 'post_type'=>'post', 'post_status'=>'publish', 'posts_per_page'=>$limit, 'ignore_sticky_posts'=>true, 'no_found_rows'=>true ]; if($data['mode']==='featured'){ $ids=bluprint_blog_ids($data['featured_order']); if(!$ids)return []; $args['post__in']=$ids; $args['orderby']='post__in'; $args['meta_query']=[[ 'key'=>'_bluprint_featured', 'value'=>'1' ]]; }elseif($data['mode']==='manual'){ $ids=bluprint_blog_ids($data['manual_ids']); if(!$ids)return []; $args['post__in']=$ids; $args['orderby']='post__in'; }else{ $args['orderby']='date'; $args['order']='DESC'; } return get_posts($args); }